chk({'layers':[],'environment':{'b':'false','i':'-04','s':''}},p2,{'ok':True,'config':{'b':False,'i':-4,'s':''},'error':None})
for key,val in [('b','False'),('b','1'),('i',' 1'),('i','1.0'),('i',True),('s',3)]: chk({'environment':{key:val}},p2,{'ok':False,'config':{},'error':'environment'})
chk({'environment':{'i':'1'}},p0,{'ok':False,'config':{},'error':'environment'})
chk({'environment':{'x':'1'}},p2,{'ok':False,'config':{},'error':'unknown_key'})
print('all assertions passed')
